create or replace function public.material_tracker_import_materials(
  p_workspace_id uuid, p_rows jsonb, p_expected_snapshot text default null, p_dry_run boolean default true
) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $function$
declare caller uuid:=auth.uid(); current_snapshot text; input_count integer; rec jsonb; fields jsonb; mapped jsonb; row_no integer; is_skipped boolean; status text; action_name text; issues jsonb; out_rows jsonb:='[]'::jsonb; valid_count integer:=0; invalid_count integer:=0; duplicate_count integer:=0; conflicting_count integer:=0; skipped_count integer:=0; material_id text; nm text; gid text; natural_key text; existing public.material_tracker_materials%rowtype; same_key public.material_tracker_materials%rowtype; seen_ids text[]:=array[]::text[]; seen_keys text[]:=array[]::text[]; server_fields jsonb; payload_patch jsonb; imported jsonb:='[]'::jsonb; created_count integer:=0; updated_count integer:=0; fx public.material_tracker_forex_rates%rowtype; mapped_key text;
begin
 if caller is null then raise exception 'authentication required' using errcode='42501'; end if;
 if not private.material_tracker_can_write(p_workspace_id) then raise exception 'Material Tracker import denied' using errcode='42501'; end if;
 if jsonb_typeof(p_rows)<>'array' then raise exception 'Import rows must be a JSON array' using errcode='22023'; end if;
 input_count:=jsonb_array_length(p_rows); if input_count<1 or input_count>5000 then raise exception 'Import must contain between 1 and 5000 rows' using errcode='22023'; end if;
 select md5(coalesce(string_agg(m.id||':'||extract(epoch from m.updated_at)::text||':'||coalesce(extract(epoch from m.archived_at)::text,''),'|' order by m.id),'')) into current_snapshot from public.material_tracker_materials m where m.workspace_id=p_workspace_id;
 if not p_dry_run and (p_expected_snapshot is null or p_expected_snapshot<>current_snapshot) then raise exception 'Import preview is stale because Material Tracker data changed. Preview the file again before committing.' using errcode='40001'; end if;
 for rec in select value from jsonb_array_elements(p_rows) loop
  row_no:=coalesce(nullif(rec->>'rowNumber','')::integer,0); fields:=coalesce(rec->'fields','{}'::jsonb); mapped:=coalesce(rec->'mappedFields','[]'::jsonb); is_skipped:=coalesce((rec->>'skipped')::boolean,false); status:='valid'; action_name:='create'; issues:='[]'::jsonb; material_id:=nullif(trim(coalesce(fields->>'id','')),''); nm:=trim(coalesce(fields->>'name','')); gid:=trim(coalesce(fields->>'groupId',''));
  if is_skipped then status:='skipped';action_name:='none';skipped_count:=skipped_count+1;issues:=jsonb_build_array(jsonb_build_object('code','user_skipped','message','Row excluded by user.'));
  else
   if nm='' then issues:=issues||jsonb_build_array(jsonb_build_object('field','name','code','required','message','name is required.')); end if;
   if length(nm)>240 then issues:=issues||jsonb_build_array(jsonb_build_object('field','name','code','max_length','message','name exceeds 240 characters.')); end if;
   if gid not in ('new_group','topics') then issues:=issues||jsonb_build_array(jsonb_build_object('field','groupId','code','accepted_value','message','groupId must be new_group or topics.')); end if;
   if coalesce(fields->>'sourceType','') not in ('Local','Import') then issues:=issues||jsonb_build_array(jsonb_build_object('field','sourceType','code','accepted_value','message','sourceType must be Local or Import.')); end if;
   if trim(coalesce(fields->>'materialDescription',''))='' then issues:=issues||jsonb_build_array(jsonb_build_object('field','materialDescription','code','required','message','materialDescription is required.')); end if;
   if length(coalesce(fields->>'materialDescription',''))>4000 then issues:=issues||jsonb_build_array(jsonb_build_object('field','materialDescription','code','max_length','message','materialDescription exceeds 4000 characters.')); end if;
   if trim(coalesce(fields->>'brand',''))='' then issues:=issues||jsonb_build_array(jsonb_build_object('field','brand','code','required','message','brand is required.')); end if;
   if length(coalesce(fields->>'brand',''))>240 then issues:=issues||jsonb_build_array(jsonb_build_object('field','brand','code','max_length','message','brand exceeds 240 characters.')); end if;
   if coalesce(fields->>'currency','') not in ('PHP','USD','EUR') then issues:=issues||jsonb_build_array(jsonb_build_object('field','currency','code','accepted_value','message','currency must be PHP, USD, or EUR.')); end if;
   if fields?'shippingCostCurrency' and fields->'shippingCostCurrency'<>'null'::jsonb and coalesce(fields->>'shippingCostCurrency','') not in ('PHP','USD','EUR') then issues:=issues||jsonb_build_array(jsonb_build_object('field','shippingCostCurrency','code','accepted_value','message','shippingCostCurrency must be PHP, USD, or EUR.')); end if;
   if not(fields?'quantity') or jsonb_typeof(fields->'quantity')<>'number' or (fields->>'quantity')::numeric<=0 then issues:=issues||jsonb_build_array(jsonb_build_object('field','quantity','code','invalid_number','message','quantity must be a number greater than zero.')); end if;
   if not(fields?'buyingPrice') or jsonb_typeof(fields->'buyingPrice')<>'number' or (fields->>'buyingPrice')::numeric<0 then issues:=issues||jsonb_build_array(jsonb_build_object('field','buyingPrice','code','invalid_number','message','buyingPrice must be a non-negative number.')); end if;
   if fields?'shippingCost' and fields->'shippingCost'<>'null'::jsonb and (jsonb_typeof(fields->'shippingCost')<>'number' or (fields->>'shippingCost')::numeric<0) then issues:=issues||jsonb_build_array(jsonb_build_object('field','shippingCost','code','invalid_number','message','shippingCost must be non-negative.')); end if;
   if fields?'leadtimeInWeeks' and fields->'leadtimeInWeeks'<>'null'::jsonb and (jsonb_typeof(fields->'leadtimeInWeeks')<>'number' or (fields->>'leadtimeInWeeks')::numeric<0 or (fields->>'leadtimeInWeeks')::numeric>520 or mod((fields->>'leadtimeInWeeks')::numeric,1)<>0) then issues:=issues||jsonb_build_array(jsonb_build_object('field','leadtimeInWeeks','code','invalid_integer','message','leadtimeInWeeks must be a whole number from 0 to 520.')); end if;
   if length(coalesce(fields->>'rfqRefNo',''))>240 then issues:=issues||jsonb_build_array(jsonb_build_object('field','rfqRefNo','code','max_length','message','rfqRefNo exceeds 240 characters.')); end if;
   if length(coalesce(fields->>'vendorDetails',''))>1000 then issues:=issues||jsonb_build_array(jsonb_build_object('field','vendorDetails','code','max_length','message','vendorDetails exceeds 1000 characters.')); end if;
   if material_id is not null and material_id!~*'^mt-[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then issues:=issues||jsonb_build_array(jsonb_build_object('field','id','code','invalid_identifier','message','id must use the Material Tracker mt-UUID format.')); end if;
   if fields?'dateRequired' and fields->'dateRequired'<>'null'::jsonb and (fields->>'dateRequired')!~'^\d{4}-\d{2}-\d{2}$' then issues:=issues||jsonb_build_array(jsonb_build_object('field','dateRequired','code','invalid_date','message','dateRequired must be normalized YYYY-MM-DD.')); end if;
   if fields?'accounts' and fields->'accounts'<>'null'::jsonb and jsonb_typeof(fields->'accounts')<>'object' then issues:=issues||jsonb_build_array(jsonb_build_object('field','accounts','code','invalid_relationship','message','accounts relationship must be a normalized object.')); end if;
   if fields?'supplierPoNo' and fields->'supplierPoNo'<>'null'::jsonb and jsonb_typeof(fields->'supplierPoNo')<>'object' then issues:=issues||jsonb_build_array(jsonb_build_object('field','supplierPoNo','code','invalid_relationship','message','supplierPoNo relationship must be a normalized object.')); end if;
   if jsonb_array_length(issues)>0 then status:='invalid';action_name:='none';invalid_count:=invalid_count+1;
   else
    natural_key:=lower(nm)||'|'||gid||'|'||case when trim(coalesce(fields->>'rfqRefNo',''))<>'' then 'rfq:'||lower(trim(fields->>'rfqRefNo')) else 'brand:'||lower(trim(coalesce(fields->>'brand','')))||'|source:'||lower(fields->>'sourceType') end;
    if material_id is not null and lower(material_id)=any(seen_ids) then status:='duplicate';action_name:='none';duplicate_count:=duplicate_count+1;issues:=jsonb_build_array(jsonb_build_object('field','id','code','duplicate_batch_id','message','The same Material Tracker id appears more than once in this import batch.'));
    elsif natural_key=any(seen_keys) then status:='duplicate';action_name:='none';duplicate_count:=duplicate_count+1;issues:=jsonb_build_array(jsonb_build_object('code','duplicate_batch_record','message','Another included row has the same normalized material identity.'));
    else
     if material_id is not null then seen_ids:=array_append(seen_ids,lower(material_id)); end if; seen_keys:=array_append(seen_keys,natural_key);
     existing:=null; if material_id is not null then select * into existing from public.material_tracker_materials m where m.workspace_id=p_workspace_id and lower(m.id)=lower(material_id) limit 1; end if;
     same_key:=null; select * into same_key from public.material_tracker_materials m where m.workspace_id=p_workspace_id and m.archived_at is null and lower(trim(m.name))||'|'||m.group_id||'|'||case when trim(coalesce(m.payload->>'rfqRefNo',''))<>'' then 'rfq:'||lower(trim(m.payload->>'rfqRefNo')) else 'brand:'||lower(trim(coalesce(m.payload->>'brand','')))||'|source:'||lower(coalesce(m.payload->>'sourceType','')) end=natural_key order by m.updated_at desc limit 1;
     if material_id is not null and existing.id is not null and existing.archived_at is not null then status:='conflicting';action_name:='none';conflicting_count:=conflicting_count+1;issues:=jsonb_build_array(jsonb_build_object('field','id','code','archived_identifier','message','The supplied id belongs to an archived material and cannot be overwritten by import.'));
     elsif material_id is not null and same_key.id is not null and same_key.id<>material_id then status:='conflicting';action_name:='none';conflicting_count:=conflicting_count+1;issues:=jsonb_build_array(jsonb_build_object('code','natural_key_conflict','message','Another active material already has the same normalized material identity.','materialId',same_key.id));
     elsif material_id is null and same_key.id is not null then status:='conflicting';action_name:='none';conflicting_count:=conflicting_count+1;issues:=jsonb_build_array(jsonb_build_object('code','existing_without_id','message','An active material matches this row. Export/re-import with its id to update it, or change the material identity.','materialId',same_key.id));
     else action_name:=case when existing.id is not null then 'update' else 'create' end;valid_count:=valid_count+1; end if;
    end if;
   end if;
  end if;
  out_rows:=out_rows||jsonb_build_array(jsonb_build_object('rowNumber',row_no,'status',status,'action',action_name,'issues',issues,'materialId',material_id));
 end loop;
 if p_dry_run then return jsonb_build_object('snapshot',current_snapshot,'canCommit',(invalid_count=0 and duplicate_count=0 and conflicting_count=0 and valid_count>0),'counts',jsonb_build_object('valid',valid_count,'invalid',invalid_count,'duplicate',duplicate_count,'conflicting',conflicting_count,'skipped',skipped_count),'rows',out_rows,'committed',false); end if;
 if invalid_count>0 or duplicate_count>0 or conflicting_count>0 or valid_count=0 then raise exception 'Import commit rejected: every included row must be valid and at least one valid row is required.' using errcode='22023'; end if;
 select * into fx from public.material_tracker_forex_rates where workspace_id=p_workspace_id;
 for rec in select value from jsonb_array_elements(p_rows) loop
  if coalesce((rec->>'skipped')::boolean,false) then continue; end if;
  fields:=coalesce(rec->'fields','{}'::jsonb);mapped:=coalesce(rec->'mappedFields','[]'::jsonb);material_id:=nullif(trim(coalesce(fields->>'id','')),'');nm:=trim(fields->>'name');gid:=fields->>'groupId';server_fields:=fields-'id'-'groupId'-'creatorId'-'creatorName'-'createdAt'-'updatedAt';
  if not(server_fields?'exRateUsd') and fx.usd is not null then server_fields:=jsonb_set(server_fields,'{exRateUsd}',to_jsonb(fx.usd),true);end if;if not(server_fields?'exRateEur') and fx.eur is not null then server_fields:=jsonb_set(server_fields,'{exRateEur}',to_jsonb(fx.eur),true);end if;
  if material_id is null then insert into public.material_tracker_materials(workspace_id,name,group_id,group_title,payload,creator_user_id) values(p_workspace_id,nm,gid,private.material_tracker_group_title(gid),server_fields,caller) returning id into material_id;insert into public.material_tracker_activity(workspace_id,material_id,text,actor_user_id) values(p_workspace_id,material_id,'Material created by atomic file import.',caller);created_count:=created_count+1;
  else
   existing:=null;select * into existing from public.material_tracker_materials m where m.workspace_id=p_workspace_id and m.id=material_id and m.archived_at is null for update;
   if existing.id is null then insert into public.material_tracker_materials(workspace_id,id,name,group_id,group_title,payload,creator_user_id) values(p_workspace_id,material_id,nm,gid,private.material_tracker_group_title(gid),server_fields,caller);insert into public.material_tracker_activity(workspace_id,material_id,text,actor_user_id) values(p_workspace_id,material_id,'Material created by atomic file import with preserved identifier.',caller);created_count:=created_count+1;
   else payload_patch:=existing.payload;for mapped_key in select value from jsonb_array_elements_text(mapped) loop if mapped_key not in ('id','name','groupId','creatorId','creatorName','createdAt','updatedAt') then if fields?mapped_key then payload_patch:=jsonb_set(payload_patch,array[mapped_key],fields->mapped_key,true);else payload_patch:=payload_patch-mapped_key;end if;end if;end loop;update public.material_tracker_materials set name=nm,group_id=gid,group_title=private.material_tracker_group_title(gid),payload=payload_patch,updated_at=now() where workspace_id=p_workspace_id and id=material_id;insert into public.material_tracker_activity(workspace_id,material_id,text,actor_user_id) values(p_workspace_id,material_id,'Material updated by atomic file import.',caller);updated_count:=updated_count+1;end if;
  end if; imported:=imported||jsonb_build_array(material_id);
 end loop;
 perform private.material_tracker_record_metric(p_workspace_id);return jsonb_build_object('snapshot',current_snapshot,'counts',jsonb_build_object('created',created_count,'updated',updated_count,'skipped',skipped_count),'materialIds',imported,'committed',true);
end;$function$;
revoke all on function public.material_tracker_import_materials(uuid,jsonb,text,boolean) from public, anon;
grant execute on function public.material_tracker_import_materials(uuid,jsonb,text,boolean) to authenticated;;
